-- The inbound landing tables for the PostgreSQL copy of the InvoiceSystem sample. Settings:
-- Tables=InboundWebhook,InboundErrorReport, InboundTables=InboundWebhook,InboundErrorReport:Payload
-- The same tables as Schemas/inbound.sql under other names, like the SQL Server copy.
CREATE TABLE IF NOT EXISTS "InboundWebhook" (
    "InboundWebhookId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Source" varchar(40) NULL,
    "EventId" varchar(80) NULL,
    "Body" varchar(4000) NOT NULL,
    "ReceivedOn" timestamp NOT NULL DEFAULT now(),
    "ProcessedOn" timestamp NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_InboundWebhook_Event" ON "InboundWebhook" ("Source", "EventId") WHERE "EventId" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "InboundErrorReport" (
    "InboundErrorReportId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" varchar(100) NULL,
    "Severity" varchar(20) NULL,
    "Payload" text NOT NULL,
    "ReceivedAt" timestamp NOT NULL DEFAULT now(),
    "IsProcessed" boolean NOT NULL DEFAULT false
);
